import { useState } from "react";
import Tooltip from "./Tooltip.index";
import Tutorial from "./Tutorial.index";
import { ToolsBoxContainer, Tools } from "./Tools.styled";
import useEcomStore from "../../store";

function ToolsBox() {
  const [isHovered, setHovered] = useState();
  const { setAppActive, setStartupFinished, setamazonExpand, setflipkartExpand } =
    useEcomStore();
  const [showGuide, setShowGuide] = useState(false);
  const handleClose = () => {
    setAppActive(false);
    setStartupFinished(false);
    setamazonExpand(false);
    setflipkartExpand(false);
  };

  return (
    <ToolsBoxContainer>
      {showGuide ? <Tutorial /> : isHovered === "help" ? <Tooltip /> : null}
      {/* <Tooltip /> */}
      <Tools
        onMouseEnter={() => setHovered("help")}
        onMouseLeave={() => setHovered()}
        hover={isHovered === "help" ? true : false}
        onClick={() => setShowGuide(!showGuide)}
      >
        ?
      </Tools>
      <Tools
        onClick={handleClose}
        onMouseEnter={() => setHovered("close")}
        onMouseLeave={() => setHovered()}
        hover={isHovered === "close" ? true : false}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="16"
          height="16"
          viewBox="0 0 16 16"
          fill="none"
        >
          <path
            d="M9.5079 8.50008L13.7912 4.21668C14.0699 3.93807 14.0699 3.48758 13.7912 3.20896C13.5125 2.93035 13.0621 2.93035 12.7834 3.20896L8.50005 7.49236L4.21678 3.20896C3.93803 2.93035 3.48768 2.93035 3.20906 3.20896C2.93031 3.48758 2.93031 3.93807 3.20906 4.21668L7.49233 8.50008L3.20906 12.7835C2.93031 13.0621 2.93031 13.5126 3.20906 13.7912C3.34791 13.9302 3.53048 14 3.71292 14C3.89536 14 4.0778 13.9302 4.21678 13.7912L8.50005 9.5078L12.7834 13.7912C12.9224 13.9302 13.1049 14 13.2873 14C13.4697 14 13.6522 13.9302 13.7912 13.7912C14.0699 13.5126 14.0699 13.0621 13.7912 12.7835L9.5079 8.50008Z"
            fill="#5C5C5C"
          />
        </svg>
      </Tools>
    </ToolsBoxContainer>
  );
}
export default ToolsBox;
