/* global chrome */

import { useEffect, useState } from "react";
import ReactDOM from "react-dom";
import ChartContainer from "../component/ChartContainer";
import Title from "../component/Title";
import { ClosingDiv, ClosingDivwrap, ErrMsg, ErrTitle, ErrorContainer, MainContainer, SearchPgBtn,LoaderContainer } from "../component/PriceTracker.styled";
import { Close } from "@mui/icons-material";

import BarChartIcon from '@mui/icons-material/BarChart';
import { usePriceTracker } from "../../context/PriceTrackerProvider";
import { dividerClasses } from "@mui/material";

function Price({priceTrackerState,setPriceTrackerState}) {

  const {
    productPgSelector,
    setProductPgSelector,
    resData,
    setResData,
    productName,
    setProductName,
    selectedValue,
    setSelectedValue,
    response,
    setResponse,
    prdtId,
    setPrdtId,
  } = usePriceTracker();

  const [loading, setLoading] = useState(false);
  const [searchPgSelectors, setSearchPgSelectors] = useState(false);
  const [prdtprice, setPrdtprice] = useState(null)

  const fetchFn = (productId) => {
    setLoading(true)

    let url = 'https://pricedata.bestbuydeals.in/product'


    fetch(url, {
      method: "POST",
      body: JSON.stringify({
        "productId": productId,
        "currentPrice": prdtprice ? prdtprice * 100 : null
      }),
      headers: {
        'Content-Type': 'application/json'
      }
    })
      .then(response => response.json())
      .then(res => {

        setProductPgSelector(true)

        if (res.error) {
          setResponse(false)

        } else if (res.length > 0) {
          setResponse(true)
          setResData(res)
          setProductName(res?.[0]?.title)
          setSelectedValue('3')
           setLoading(false)
        }
      })
  }

  const initFn = () => {
    let pgUrl = window.location.pathname

    if (pgUrl.includes('/dp/')) {
      let price = document.querySelector('#twister-plus-price-data-price')

      const regex = /\/dp\/([A-Za-z0-9]+)/;

      let productId = pgUrl.match(regex)[1]
      setPrdtId(productId)
      setPrdtprice(price.value)

    } else if (pgUrl === '/s') {
      setProductPgSelector(false)
      setSearchPgSelectors(false)
      setTimeout(() => {
        setSearchPgSelectors(true)
      }, 2000)



    }
  }

  useEffect(() => {
    if (prdtId) {
      setProductPgSelector(false)
      fetchFn(prdtId)

    }

  }, [prdtId])


  useEffect(() => {
    chrome.runtime.onMessage.addListener(ReceivedMessage);
    // return () => {
    //   window.chrome.runtime.onMessage.removeListener(ReceivedMessage)
    // }
  }, [])

  const ReceivedMessage = (request) => {
    if (request.message === 'PageUpdated') {
      initFn()
      
    }
  }

  const closeFn = (value) => {
    setProductPgSelector(value)
    setPrdtId(null)
  }



  const trackPrice = (elem) => {
    setLoading(true)
    let price = parseFloat(elem.querySelector('.a-price-whole').innerText.replace(/,/g, ''))
    let productId = elem.getAttribute('data-asin')

    setPrdtId(productId);
    setPrdtprice(price);
    setTimeout(() => {
      setLoading(false); // Hide the loader once data is available
    }, 2000);
  }

  // const getImage = (path) => {
  //   return chrome.runtime.getURL(path)
  // }
  return (
    <>
      {loading ? (
        <ErrorContainer>
          {/* <img src={ getImage("icons/loading.gif") } className="loading-icon" alt="loading.." 
          style={{width:"70px", height:"40px"}} /> */}
          <LoaderContainer>
            <div className="loader"></div>
          </LoaderContainer>
        </ErrorContainer>
      ) : (
        <>
          {
            productPgSelector && priceTrackerState && (
              !response ? (
                <ErrorContainer>
                  <ClosingDivwrap>
                    <ClosingDiv onClick={() => {
                      setProductPgSelector(false)
                    }}
                    style={{ position: "absolute", right: "-295px", top: "-10px" }}>
                      <Close />
                    </ClosingDiv>
                  </ClosingDivwrap>

                  <ErrTitle>Price Tracker for Amazon</ErrTitle>

                  <ErrMsg>Product Data Not Available</ErrMsg>

                </ErrorContainer>
              ) : (
                <MainContainer>
                  <Title close={closeFn} />
                  <ChartContainer />
                </MainContainer>
              )
            )
          }
          {
            searchPgSelectors &&
            document.querySelectorAll('[data-component-type="s-search-result"]').forEach((element, index) => {

              element.style.position = 'relative'
              const reactRoot = document.createElement("div");
              element.appendChild(reactRoot);

              ReactDOM.render(<SearchPgBtn inGrid List onClick={() =>{
                setPriceTrackerState(true)
                trackPrice(element)
              }}><BarChartIcon style={{ backgroundColor: "lightblue", fontSize: "35px", Left: "500px" }} />  </SearchPgBtn>, reactRoot);
            })

          }
        </>
      )}
    </>
  );

}

export default Price;
