import CanvasJSReact from '@canvasjs/react-charts';
import { ChartWrapper, DetailSec, MidSectionWrapper } from './PriceTracker.styled';
import { useEffect, useRef, useState } from 'react';
import { usePriceTracker } from '../../context/PriceTrackerProvider';

var CanvasJS = CanvasJSReact.CanvasJS;
var CanvasJSChart = CanvasJSReact.CanvasJSChart;

const ChartContainer = (props) => {

    const {

        resData,
        selectedValue,
    } = usePriceTracker();

    const [dataArr, setDataArr] = useState(null)
    const [maxPrice, setMaxPrice] = useState(0)
    const [minPrice, setMinPrice] = useState(0)
    const [currentPrice, setCurrentPrice] = useState(0)
    const [prdtImg, setPrdtImg] = useState(null)
    const chartRef = useRef(null);

    const priceExtractor = (tempArr) => {
        if (tempArr.length > 0) {
            let priceArr = tempArr.map(item => item.y);
            setMaxPrice(Math.max(...priceArr))
            setMinPrice(Math.min(...priceArr))
        } else {
            setMaxPrice(0)
            setMinPrice(0)
        }

    }


    useEffect(() => {
        if (resData) {
            let resetBtn = document.querySelector('[title="Reset"]')
            if (resetBtn) {
                resetBtn.click()
            }
            let imgLink = resData[0].images_csv.split(',')[0];
            setPrdtImg(`https://images-na.ssl-images-amazon.com/images/I/${imgLink}`);
            let tempArr = [];
            let filteredData = resData;
            const selectedValue1 = selectedValue || '3'

            // Filter data based on selected value
            if (selectedValue1 === '6') {
                const sixMonthsAgo = new Date();
                sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
                filteredData = filteredData.filter(item => new Date(item.date) >= sixMonthsAgo);
            } else if (selectedValue1 === '3') {
                const threeMonthsAgo = new Date();
                threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);
                filteredData = filteredData.filter(item => new Date(item.date) >= threeMonthsAgo);
            }
            filteredData.forEach((element, index) => {
                let formattedDate = new Date(element.date);
                let elemPrice = parseInt(element.price / 100);
                setCurrentPrice(elemPrice);

                let obj = {
                    x: formattedDate,
                    y: elemPrice,
                };
                tempArr.push(obj);
            });

            setDataArr(tempArr);
            priceExtractor(tempArr);

            if (chartRef.current) {
                // Reset zoom when the data or selectedValue changes
                chartRef.current.render();
            }
        }
    }, [resData, selectedValue]);


    const options = {
        animationEnabled: true,
        // exportEnabled: true,
        zoomEnabled: true,
        title: {
            text: "Price Tracker for Amazon",
            fontSize: 24,
            fontFamily: 'Roboto, sans-serif',
            fontColor: '#0F1111'
        },
        axisY: {
            title: "Price",
            includeZero: true
        },
        axisX: {
            // title: "Date",
            valueFormatString: "DD/MM/YY",
            interval: 5,
            type: "scrolling",
        },
        data: [
            {
                type: "stepArea",
                // xValueFormatString: "DD/MM/YYYY" ,
                dataPoints: dataArr

            }
        ]
    }

    return (
        <MidSectionWrapper>
            <ChartWrapper>
                <CanvasJSChart options={options} ref={chartRef} />
            </ChartWrapper>
            <DetailSec>
                <div id='prdtImg'>
                    <img src={prdtImg} alt='image' />

                </div>
                <div id='CurPrice'>
                    <div className='priceText'>Current Price:</div>
                    <div className='prdtprice' id='currentPriceId'
                        style={{ color: currentPrice == maxPrice ? "red" : currentPrice == minPrice ? 'green' : '#FFA41C' }}
                    >
                        ₹{currentPrice.toLocaleString()}
                    </div>
                </div>
                <div id='HighPrice'>
                    <div className='priceText'>Highest Price:</div>
                    <div className='prdtprice' id='highPriceId'>
                        ₹{maxPrice.toLocaleString()}
                    </div>
                </div>
                <div id='LowPrice'>
                    <div className='priceText'>Lowest Price:</div>
                    <div className='prdtprice' id='lowPriceId' >
                        ₹{minPrice.toLocaleString()}
                    </div>
                </div>

            </DetailSec>
        </MidSectionWrapper >
    )
}

export default ChartContainer

