/* global chrome */
import {
  StartupContainer,
  FooddyLogoContainer,
  FoodyText,
  Logo,
  DishesImage,
} from "./Startup.styled";
import Strings from "../../constants/Strings";
import useEcomStore from "../../store";
import { useEffect } from "react";
const FoodTray = chrome.runtime.getURL("./Icons/food-tray.png");
const Dishes = chrome.runtime.getURL("./Icons/dishes.png");
const FooddyLogo = chrome.runtime.getURL("./Icons/foodyText.png");
function Startup() {
  const { setStartupFinished, isStartupFinished } = useEcomStore();
  useEffect(() => {
    setTimeout(() => setStartupFinished(true), 1000);
  }, []);
  return (
    <StartupContainer>
      <FooddyLogoContainer>
        {isStartupFinished && <Logo draggable={false} src={FoodTray} />}
        <FoodyText src={FooddyLogo} />
      </FooddyLogoContainer>
      <DishesImage draggable={false} src={Dishes} alt="img" />
    </StartupContainer>
  );
}

export default Startup;
