//checking the oreders page
function checkForOrderWord() {
  const url = window.location.href.toLowerCase();
  return /order|orders/.test(url);
}

export function checkingOrderUrl() {
  if (checkForOrderWord()) {
    return true;
  } else {
    return false;
  }
}

