export const amazonUserDetails = async () => {
  try {
    const secondPageUrl = await mainPagefunc();

    if (!secondPageUrl) throw new Error("Something went wrong!");

    const { phoneNumber, email, profileName } = await secondPagefunc(secondPageUrl);
    return { phoneNumber, email, profileName };
  } catch (error) {
    console.log(error);
  }
};

const mainPagefunc = async () => {
  const linkElement = document.getElementById("nav-link-accountList")?.querySelector('a')

  if (linkElement) {
    // Get the value of the href attribute
    const link = linkElement.href;
    if (link) {
      try {
        // Make a request to the linked page
        const response = await fetch(link);
        const html = await response.text();

        const parser = new DOMParser();
        const linkedDocument = parser.parseFromString(html, "text/html");

        const inputElement = linkedDocument.querySelectorAll(
          ".ya-card__whole-card-link"
        )?.[1];
        const secondPageLink = inputElement.href;
        return secondPageLink;
      } catch (error) {
        console.error("Error:", error);
        throw error;
      }
    }
  }
};

const secondPagefunc = async (seconPageUrl) => {
  try {
    // Make a request to the linked page
    const response = await fetch(seconPageUrl);
    const html = await response.text();
    // Process the HTML content

    // Parse the HTML content into a document
    const parser = new DOMParser();
    const linkedDocument = parser.parseFromString(html, "text/html");

    const SingnIn = linkedDocument.querySelector(".a-spacing-small").textContent.trim();
    // Extract information (for example, paragraphs)
    // const ifMobileNum =
    //   linkedDocument.querySelectorAll(".a-row")?.[7]?.innerText ??
    //   linkedDocument.querySelectorAll(".a-row")?.[4]?.innerText;\
    let phoneNumber = linkedDocument?.querySelector('#MOBILE_NUMBER_SUBTITLE')?.innerText?.trim() ?? null
    // const getmobileOrEmail =
    //   linkedDocument.querySelector(".a-color-tertiary ")?.innerText ??
    //   ifMobileNum;
    let email = linkedDocument?.querySelector('#EMAIL_SUBTITLE')?.innerText?.trim() ?? null
    let profileName = linkedDocument?.querySelector('#NAME_SUBTITLE')?.innerText?.trim() ?? null

    let primarylogin = linkedDocument?.querySelector("#authportal-main-section")?.querySelector('.auth-prompt-section')?.querySelector('.auth-prompt-profile-details')?.querySelectorAll('.auth-text-truncate')[1]?.textContent?.trim() ?? null
    let primaryProfileLoginName = linkedDocument?.querySelector("#authportal-main-section")?.querySelector('.auth-prompt-section')?.querySelector('.auth-prompt-profile-details')?.querySelectorAll('.auth-text-truncate')[0]?.textContent?.trim() ?? null
    if (primarylogin) {
      if (primarylogin?.includes('@')) {
        email = email ? email : primarylogin
      }
      else {
        phoneNumber = phoneNumber ? phoneNumber : primarylogin
      }
    }
    if (primaryProfileLoginName) {
      profileName = profileName ? profileName : primaryProfileLoginName
    }
    return { phoneNumber, email, profileName };
  } catch (error) {
    console.error("Error:", error);
    throw error;
  }
};

let FetchApi = async (page) => {
  return new Promise((resolve, reject) => {
    fetch(page)
      .then((res) => res.text())

      .then((data) => {
        initialData = data;

        const parser = new DOMParser();

        let dom = parser.parseFromString(initialData, "text/html");

        //Processing the dom for each page of an year

        // findAmazonOrders(dom);

        resolve(dom);
      })

      .catch((err) => {
        console.log(err);

        reject(err);
      });
  });
};

