function generateRandomFourDigitNumber() {
  // Generate a random number between 1000 and 9999 (inclusive)
  return Math.floor(Math.random() * (9999 - 1000 + 1)) + 1000;
}

const userDetailsamazon = async (extensionId) => {
  const details = {};
  const user_name = localStorage.getItem("displayName");
  const gender = localStorage.getItem("gender");
  const { phoneNumber, email, profileName } = await amazonUserDetails();
  const spender_id = `${user_name.slice(
    0,
    4
  )}${generateRandomFourDigitNumber()}`;
  details.user_name = user_name;
  details.gender = gender;
  details.spender_id = spender_id;
  details.profileName = profileName;
  // if (gettingUserPhoneOrEmail.includes("@")) {
  //   const user_email = gettingUserPhoneOrEmail.trim();
  //   details.user_email = user_email;

  //   return details;
  // } else {
  //   const user_phone_number = gettingUserPhoneOrEmail.trim();
  //   details.user_phone_number = user_phone_number;
  //   return details;
  // }
  details.extensionId = extensionId ?? null
  details.user_email = email ?? null
  details.user_phone_number = phoneNumber ?? null
  return details
};

const dataTosend = async (extensionId) => {
  const dataToBackend = {};

  try {
    const userDetails = await userDetailsamazon(extensionId);
    // Get the years
    const ele = document.querySelector(".a-native-dropdown");
    const years = Array.from(ele.options)
      .map((option) => option.innerText.replace(/\s+/g, ""))
      .filter((data) => !isNaN(data))
      .map(Number);

    // Extract order details from each page

    for (const year of years) {
      // const yearPageUrl = `https://www.amazon.in/gp/css/order-history?opt=ab&digitalOrders=1&unifiedOrders=1&returnTo=&orderFilter=year-${year}&startIndex=0&language=en_GB&disableCsd=no-js`;
      const yearPageUrl = `https://www.amazon.in/your-orders/orders?timeFilter=year-${year}&ref_=ppx_yo2ov_dt_b_filter_all_y${year}`;
      const response = await fetch(yearPageUrl);
      const data = await response.text();
      const parser = new DOMParser();
      const dom = parser.parseFromString(data, "text/html");
      let pageCount = 1;
      const a = dom.getElementsByClassName("a-pagination")?.[0];
      if (a) {
        const aa = a?.outerText?.split("\n");
        let aa1 = aa.filter((e) => e && e.trim() !== "")
        pageCount = Number(aa1.at(-2).trim());
      }
      for (let i = 0; i < pageCount; i++) {
        // const pageUrl = `https://www.amazon.in/gp/css/order-history?opt=ab&digitalOrders=1&unifiedOrders=1&returnTo=&orderFilter=year-${year}&startIndex=${i * 10
        //   }&language=en_GB&disableCsd=no-js`;
        const pageUrl = `https://www.amazon.in/your-orders/orders?timeFilter=year-${year}&startIndex=${i * 10}&language=en_GB&disableCsd=no-js`
        const dot = await FetchApi(pageUrl);
        await findAmazonOrders(dot);
      }
    }

    // Get user details and order details

    userDetails.total_amount_spent =
      amazonOrderedItems.reduce((partialSum, obj) => {
        if (
          typeof obj.total_order_amount === "number" &&
          !isNaN(obj.total_order_amount)
        ) {
          return partialSum + obj.total_order_amount;
        } else {
          return partialSum;
        }
      }, 0) ?? null;
    dataToBackend.userDetails = userDetails;
    dataToBackend.dataDetails = amazonOrderedItems;
    return dataToBackend;
  } catch (error) {
    console.error(error);
    // Handle errors
  }
};

export const FinalObjectOfAmazon = async (
  setInternalFetching,
  setamazonExpand,
  setAppActive,
  extensionId
) => {
  try {
    const data = await dataTosend(extensionId);
    const response = await fetch(
      "https://sc.ecombullet.com/api/amazon/insert",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "ngrok-skip-browser-warning": true,
        },
        body: JSON.stringify(data),
      }
    );
    if (response) {
      const responseData = await response.json();
      setInternalFetching(false);
      setamazonExpand(false);
      setAppActive(false);
      amazonOrderedItems = [];
      const url = `https://app.ecombullet.com/${responseData.userDetails.id}/amazon/${responseData.userDetails.spenderId}`;
      window.open(url);
    }
  } catch (error) {
    console.log(error);
  }
};
