import styled, { keyframes } from "styled-components";

export const fadeUp = keyframes`
    0% {
        top: 91px; 
        opacity: 100%;
    }
    100% {
        top: -137px;
        opacity: 16%;
    }
`;

export const slideRight = (start, end, opacityFading) => keyframes`
    0% {
        opacity: 100%;
        left: ${start}px;
    }
    50%{
        opacity: ${opacityFading ? "50%" : "100%"};
        left: ${start + (end - start) / 2}px;
    }
    100%{
        opacity: ${opacityFading ? "0%" : "100%"};
        left: ${end}px;
    }
`;

export const StartupContainer = styled.div`
  position: relative;
  height: 100%;
  width: 100%;
`;

