import {
  TutorialContainer,
  TutorialHeading,
  Steps,
  Step,
  SerialNo,
  Content,
} from "./Tutorial.styled";
import { Triangle } from "./Tooltip.styled";
import Strings from "../../constants/Strings";
function Tutorial() {
  const getSteps = () => {
    const allSteps = Strings.guide.map((point, index) => {
      return (
        <Step>
          <SerialNo>{`${index + 1}.`}</SerialNo>
          <Content>{point}</Content>
        </Step>
      );
    });
    return allSteps;
  };
  return (
    <TutorialContainer>
      <TutorialHeading>{Strings.guideLabel}</TutorialHeading>
      <Triangle tutorial />
      <Steps>{getSteps()}</Steps>
    </TutorialContainer>
  );
}

export default Tutorial;
