const pageScroll = (extensionId) => {
  return new Promise(async (resolve, reject) => {
    try {
      window.scrollBy(0, 1400);
      var scrolldelay = setTimeout(async () => {
        var showMore = document.querySelector(".QqFHMw.v0q-qo");

        var finalResult;
        if (showMore) showMore.click();

        if (
          document
            .getElementsByClassName("v0q-qo")?.[0]
            ?.outerText.includes("No")
        ) {
          clearTimeout(scrolldelay);
          finalResult = await dataToSend(extensionId);

          resolve(finalResult); // Resolve the promise with finalResult
        } else {
          pageScroll(extensionId).then(resolve).catch(reject);
        }
      }, 2000);
    } catch (err) {
      reject(err);
    }
  });
};

function generateRandomFourDigitNumber() {
  return Math.floor(Math.random() * (9999 - 1000 + 1)) + 1000;
}

//create slug function 
function createSlug(text) {
  if (!text) return null;
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-');
}

//getIso string 
const getISOString = (order_placed_time) => {
  if (!order_placed_time) return null;

  const date = new Date(order_placed_time);
  return isNaN(date.getTime()) ? null : date.toISOString();
}

export const flipkartUserDetails = async () => {
  const linkElement = document.querySelectorAll('.R0cyWM')?.[1];
  if (linkElement) {
    const link = linkElement.getAttribute("href");
    if (link) {
      try {
        const response = await fetch(link);
        const html = await response.text();
        const parser = new DOMParser();
        const linkedDocument = parser.parseFromString(html, "text/html");
        const mobNumber = linkedDocument.querySelector(
          "input[name='mobileNumber']"
        )?.value;
        const userEmail = linkedDocument.querySelector(
          "input[name='email']")?.value
        let firstProfileName = linkedDocument.querySelector("input[name='firstName']")?.value ? linkedDocument.querySelector("input[name='firstName']")?.value : null
        let secondProfileName = linkedDocument.querySelector("input[name='lastName']")?.value ? linkedDocument.querySelector("input[name='lastName']")?.value : null
        let profileName = '';
        if (firstProfileName) profileName += firstProfileName
        if (secondProfileName) profileName = profileName + " " + secondProfileName
        if (!profileName) profileName = null
        else {
          profileName = profileName.trim()
        }
        const user_phone_number = mobNumber;
        // const user_name = linkedDocument.querySelector(".exehdJ").innerText;
        const user_name = localStorage.getItem("displayName") ?? null
        const gender = localStorage.getItem("gender");
        const spender_id = `${user_name.slice(
          0,
          4
        )}${generateRandomFourDigitNumber()}`;
        const user_email = userEmail ?? null
        const user_details = {
          user_name,
          user_phone_number,
          spender_id,
          gender,
          user_email,
          profileName,
        };
        return user_details;
      } catch (error) {
        console.error("Error:", error);
      }
    }
  }
};
let dataDetails = [];
const flipkartOrderDetails = async () => {
  // let dataDetails = [];
  const all = document.querySelectorAll(".ejrH5a");
  for (let l = 0; l < all.length; l++) {
    const urlElement = all[l]?.querySelector("._9rRUNC")?.href;
    const flipkart_order_id = urlElement?.split("=")[1]?.split("&")[0];
    const product_name = all[l]?.querySelector(
      "._4teGKY"
    )?.textContent;
    const product_image_url = all[l]
      ?.querySelector(".DByuf4")
      ?.getAttribute("src");
    const flipkart_product_id = createSlug(product_name)
    let product_price = 0;
    const elements = all[l]?.querySelectorAll(".col-2-12.mcVLQq");
    if (elements.length > 0) {
      const priceText = elements[0]?.innerText;
      const priceParts = priceText?.split("+");
      if (priceParts.length >= 1) {
        const halfPrice = parseFloat(priceParts[0]?.replace(/[^\d.]/g, ""));
        if (priceParts.length === 2) {
          const supercoinValue = parseFloat(
            priceParts[1].replace(/[^\d.]/g, "")
          );
          product_price = halfPrice + supercoinValue;
        } else {
          product_price = halfPrice;
        }
      }
    }
    let DeliveryStatus = all[l]?.querySelector(".g1SRZp")?.innerText;
    // let ModifiedDeliveryStatus = DeliveryStatus?.trim();
    let DelivArray = DeliveryStatus?.split(" ");
    let order_placed_time;

    if (DelivArray.length >= 4) {
      const currentYear = new Date().getFullYear();
      const lastPart = DelivArray[DelivArray.length - 1];

      // Check if the last part is a year (four digits)
      if (/^\d{4}$/.test(lastPart)) {
        order_placed_time = DelivArray.slice(1, -1).join(" ") + " " + lastPart;
      } else {
        order_placed_time = DelivArray.slice(1).join(" ") + " " + currentYear;
      }
    }
    if (DeliveryStatus?.includes("Delivered")) {
      const product_object = {
        flipkart_product_id,
        product_name,
        product_image_url,
        product_price,
      };
      const existingOrder = dataDetails.find(
        (order) => order.flipkart_order_id === flipkart_order_id
      );
      if (existingOrder) {
        existingOrder.productData.push(product_object);
        existingOrder.total_order_amount += product_price;
      } else {
        const order_object = {
          flipkart_order_id,
          total_order_amount: product_price,
          order_placed_time: getISOString(order_placed_time),
          productData: [product_object],
        };
        dataDetails.push(order_object);
      }
    }
  }
};

const dataToSend = async (extensionId) => {
  const userDetails = await flipkartUserDetails();
  await flipkartOrderDetails();
  const totlAmount = Array.isArray(dataDetails) ? dataDetails.reduce((partialSum, obj) => {
    if (
      typeof obj?.total_order_amount === "number" &&
      !isNaN(obj?.total_order_amount)
    ) {
      return partialSum + obj?.total_order_amount;
    } else {
      return partialSum;
    }
  }, 0) : null;
  userDetails.total_amount_spent = totlAmount;
  userDetails.extensionId = extensionId
  const dataToBackend = { userDetails, dataDetails };
  // console.log(dataToBackend)
  return dataToBackend;
};

export const FinalObjectOfFlipkart = async (
  setInternalFetching,
  setflipkartExpand,
  setAppActive,
  extensionId
) => {
  try {
    const result = await pageScroll(extensionId);
    const response = await fetch(
      "https://sc.ecombullet.com/api/flipkart/insert",
      {
        method: "POST",

        headers: {
          "Content-Type": "application/json",

          "ngrok-skip-browser-warning": true,
        },

        body: JSON.stringify(result),
      }
    );

    if (response) {
      const responseData = await response.json();

      setInternalFetching(false);
      setflipkartExpand(false);
      setAppActive(false);
      dataDetails = [];
      const url = `https://app.ecombullet.com/${responseData.userDetails.id}/flipkart/${responseData.userDetails.spenderId}`;

      window.open(url);
    }
  } catch (error) {
    console.log(error);
  }
};



