/* global chrome */
import { MyApp } from "./root.styled";

import Startup from "../Startup/Startup.index";
import HeadingText from "../HeadingText/HeadingText.index";
import Content from "../Content/Content";
import ToolsBox from "../Tools/Tools.index";
import useEcomStore from "../../store";
import { GlobalStyle } from "../../globalStyles";
import { useEffect } from "react";
import Strings from "../../constants/Strings";
import Loader from "../Loader";
import axios from "axios";
import {
  FinalObject,
  FinalObjectOfAmazon,
  amazonLoginStatus,
} from "../../utils/Amazon";
import { v4 as uuidv4 } from "uuid";
import { useState } from "react";
import {
  FinalObjectOfFlipkart,
  FlipkartoLoginStatus,
  flipkartUserDetails,
  gettingMobOrEmailFromflipkart,
} from "../../utils/Flipkart";
import { amazonUserDetails } from "../../utils/Amazon";
import { checkingOrderUrl } from "../../utils/Amazon";
function Root({ priceTrackerState, setPriceTrackerState }) {
  const {
    extensionId,
    backendUrl,
    isAppActive,
    setAppActive,
    setAmazonPage,
    setFlipkartPage,
    isInternalFetching,
    setInternalFetching,
    isAmazonLoggedIn,
    setAmazonLoggedIn,
    isFlipkartLoggedIn,
    setFlipkartLoggedIn,
    isAmazonPage,
    isFlipkartPage,
    setDisplayName,
    setecomUrl,
    setSpenderId,
    spenderId,
    setamazonAnalyzeState,
    setflipkartAnalyzeState,
    displayName,
    isStartupFinished,
    gender,
    setGender,
    userCount,
    setUserCount,
    setOldUser,
    isOldUser,
  } = useEcomStore();
  const [checkingExistingUser, setCheckingExistingUser] = useState(false);
  chrome.runtime.onMessage.addListener((message) => {
    const { appClicked, urlChanged } = message;
    if (appClicked) {
      setPriceTrackerState(false)
      setAppActive(message.appClicked);
    }
    if (urlChanged) identifyPage();
  });

  const identifyPage = () => {
    const currentPage = window.location.href;
    if (currentPage.includes(Strings.swiggyPrefixUrl)) {
      setAmazonPage(true);
      return;
    }
    if (currentPage.includes(Strings.zomatoPrefixUrl)) {
      setFlipkartPage(true);
      return;
    }
  };

  const getUserCount = async () => {
    try {
      const responseData = await fetch(
        `${backendUrl}/api/dashboard/totalusers`
      );
      const data = await responseData.json();
      const { amazonUsers, flipkartUsers } = data;
      setUserCount({
        swiggy: Math.ceil(amazonUsers / 1000),
        zomato: Math.ceil(flipkartUsers / 1000),
      });
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    identifyPage();
    getUserCount();
   
  }, []);

  useEffect(() => {
    if (isAmazonPage) {
      setAmazonLoggedIn(amazonLoginStatus());
    }
    if (isFlipkartPage) {
      setFlipkartLoggedIn(FlipkartoLoginStatus());
    }

    if (amazonLoginStatus()) {
    }
  }, [isAppActive, isAmazonPage, isFlipkartPage]);

  const backendCheck = async (platform, data) => {
    /* backend fetching for checking user exists or not */
    const response = await axios.post(
      `${backendUrl}/api/${platform}/existingusers${platform}`,
      data
    );

    if (response) setCheckingExistingUser(false);
    const responseData = response.data;
    setOldUser(responseData?.oldUser);

    if (responseData?.oldUser) {
      if (checkingOrderUrl()) {
        setDisplayName(responseData["userDetails"]?.userName);
        setGender(responseData["userDetails"]?.gender);
        localStorage.setItem("displayName", responseData["userDetails"]?.userName);
        localStorage.setItem("gender", responseData["userDetails"]?.gender);
      }
    } else {
      // new user
      chrome.storage.local.set({
        displayName: undefined,
        spenderId: undefined,
        userDetails: {
          zomatoUserid: isFlipkartPage ? uuidv4() : undefined,
          swiggyUserid: isAmazonPage ? uuidv4() : undefined,
        },
      });
      setDisplayName();
      setecomUrl();
    }
  };

  const isUserExistsInZomato = async () => {
    try {
      const { phoneNumber, email } = await gettingMobOrEmailFromflipkart();
      const dataToSend = { phoneNumber, email, extensionId, };
      backendCheck("flipkart", dataToSend);
    } catch (error) {

    }
  };

  const isUserExistsInSwiggy = async () => {
    const { phoneNumber, email } = await amazonUserDetails();
    // if (getEmailOrMobnum?.includes("@")) {
    //   const email = getEmailOrMobnum?.trim();
    //   const dataToSend = { email };
    //   backendCheck("amazon", dataToSend);
    // } else {
    //   const phoneNumber = getEmailOrMobnum?.trim();
    //   const dataToSend = { phoneNumber };
    //   await backendCheck("amazon", dataToSend);
    // }

    await backendCheck("amazon", { phoneNumber, email, extensionId, });
  };

  useEffect(() => {
   
      if (isFlipkartLoggedIn) {
        // setInternalFetching(true);
        setCheckingExistingUser(true);
        isUserExistsInZomato().then(() => setInternalFetching(false));
      }
      if (isAmazonLoggedIn) {
        setInternalFetching(true);
        isUserExistsInSwiggy().then(() => setInternalFetching(false));
      }
    // if (isFlipkartLoggedIn) {
    //   // setInternalFetching(true);
    //   setCheckingExistingUser(true);
    //   isUserExistsInZomato().then(() => setInternalFetching(false));
    // }
    // if (isAmazonLoggedIn) {
    //   setInternalFetching(true);
    //   isUserExistsInSwiggy().then(() => setInternalFetching(false));
    // }
  }, [isAmazonLoggedIn, isFlipkartLoggedIn, isAmazonPage, isFlipkartPage]);

  if (!isAppActive || priceTrackerState) return null;
  if (isInternalFetching || !userCount)
    return (
      <MyApp>
        <GlobalStyle />
        <Loader
          loadingTextNeeded={
            (isAmazonLoggedIn || isFlipkartLoggedIn) && gender
              ? // checkingOrderUrl
              true
              : false
          }
        />
      </MyApp>
    );

  return (
    <MyApp>
      <GlobalStyle />
      <ToolsBox />
      <Startup />
      {isStartupFinished ? <HeadingText /> : null}
      {isStartupFinished ? <Content /> : null}
    </MyApp>
  );
}

export default Root;
