/* global chrome */
import Strings from "../../constants/Strings";
import CardTemplate from "../CardTemplate/CardTemplate.index";
import GetCardContent from "./GetCardContent";
import { ContentContainer, CalculateButton } from "./Content.styled";
import useEcomStore from "../../store";
import { useState } from "react";
import { useEffect } from "react";
import { FinalObjectOfAmazon } from "../../utils/Amazon";
import { FinalObjectOfFlipkart } from "../../utils/Flipkart";
function Content() {
  const {
    extensionId,
    isStartupFinished,
    isAmazonPage,
    isFlipkartPage,
    isAmazonLoggedIn,
    isFlipkartLoggedIn,
    setInternalFetching,
    spenderId,
    setecomUrl,
    setSpenderId,
    displayName,
    gender,
    amazonNoOrders,
    flipkartNoOrders,
    setamazonNoOrders,
    setflipkartNoOrders,
    amazonExpand,
    setamazonExpand,
    flipkartExpand,
    setflipkartExpand,
    setAppActive,
  } = useEcomStore();
  const [isSwiggyClicked, setSwiggyClicked] = useState(false);
  const [isZomatoClicked, setZomatoClicked] = useState(false);

  function createIDWithTimestamp() {
    const timestamp = Date.now(); // Get the current timestamp in milliseconds

    const randomID = Math.floor(Math.random() * 2000000); // Generate a random number between 0 and 999

    const idWithTimestamp = `${displayName.substring(0, 6)}${String(
      randomID
    ).substring(0, 4)}`; // Concatenate the timestamp and random number

    setSpenderId(idWithTimestamp);
    return idWithTimestamp;
  }

  const checkOrSetId = async () => {
    const id = spenderId ? spenderId : createIDWithTimestamp();
    return id;
  };
  const analyzingData = async () => {

    const currentPage = window.location.href;
    const nameFromStorage = localStorage.getItem("displayName");
    const genderFromStorage = localStorage.getItem("gender");
    if (displayName !== null && gender !== undefined) {
      if (currentPage.includes(Strings.swiggyPrefixUrl)) {
        await FinalObjectOfAmazon(setInternalFetching, setamazonExpand, setAppActive,extensionId);
      } else if (currentPage.includes(Strings.zomatoPrefixUrl)) {
        await FinalObjectOfFlipkart(setInternalFetching, setflipkartExpand, setAppActive,extensionId);
      }
    }
  };
  const handleSwiggyAnalyze = async () => {
    if (!isAmazonPage) {
      //login state
      chrome.runtime.sendMessage({
        createTab: true,
        url: Strings.swiggyUrl,
      });
      return;
    }

    if (!isAmazonLoggedIn || !gender || !displayName) {
      setamazonExpand(true);
      return;
    } else {
      setInternalFetching(true);
      await analyzingData();
      return;
    }
  };

  const handleZomatoAnalyze = async () => {
    if (!isFlipkartPage) {
      //login state
      chrome.runtime.sendMessage({
        createTab: true,
        url: Strings.zomatoUrl,
      });
      return;
    }
    if (!isFlipkartLoggedIn || !gender || !displayName) {
      setflipkartExpand(true);
      return;
    } else {
      setInternalFetching(true);
      await analyzingData();
      return;
    }
  };

  useEffect(() => {
    if (isSwiggyClicked) {
      handleSwiggyAnalyze();
    }
    if (isZomatoClicked) {
      handleZomatoAnalyze();
    }
  }, [isSwiggyClicked, isZomatoClicked]);

  const analyze = async () => {
    setInternalFetching(true);
    localStorage.setItem("displayName", displayName);
    localStorage.setItem("gender", gender);

    if (amazonNoOrders || flipkartNoOrders) {
      setamazonExpand(false);
      setamazonNoOrders(false);
      setflipkartExpand(false);
      setflipkartNoOrders(false);
      return;
    }

    await analyzingData();
  };
  if (!isStartupFinished) return;
  return (
    <ContentContainer expand={amazonExpand || flipkartExpand ? true : false}>
      <CardTemplate
        name="swiggy"
        disable={
          (isFlipkartPage && isZomatoClicked) || flipkartExpand ? true : false
        }
        expand={amazonExpand}
        setClicked={setSwiggyClicked}
      >
        {amazonExpand ? (
          <GetCardContent
            contentFor={"swiggy"}
            logged={isAmazonLoggedIn ? true : false}
            noOrders={amazonNoOrders ? true : false}
          />
        ) : (
          <GetCardContent contentFor="both" />
        )}
      </CardTemplate>
      <CardTemplate
        name="zomato"
        disable={
          (isAmazonPage && isSwiggyClicked) || amazonExpand ? true : false
        }
        expand={flipkartExpand}
        setClicked={setZomatoClicked}
      >
        {flipkartExpand ? (
          <GetCardContent
            contentFor={"zomato"}
            logged={isFlipkartLoggedIn ? true : false}
            noOrders={flipkartNoOrders ? true : false}
          />
        ) : (
          <GetCardContent contentFor="both" />
        )}
      </CardTemplate>
      {amazonExpand || flipkartExpand ? (
        <CalculateButton
          active={
            displayName && displayName.length > 3 && gender ? true : false
          }
          onClick={analyze}
        >
          {isAmazonLoggedIn || isFlipkartLoggedIn
            ? amazonNoOrders || flipkartNoOrders
              ? Strings.backToHomepage
              : Strings.showResults
            : Strings.calculateButton}
        </CalculateButton>
      ) : null}
    </ContentContainer>
  );
}

export default Content;
