import styled, { keyframes } from "styled-components";

export const MainContainer = styled.div`
height: 400px;
width: 600px;
background-color: #fff;
position: fixed;
bottom: 5px;
right: 5px;
z-index: 9999999999;
padding: 5px;
outline: 1px solid black;
`
export const ClosingDivwrap = styled.div`
width: auto;
position: relative;
`

export const ErrorContainer = styled.div`
height: 100px;
width: 600px;
background-color: #fff;
position: fixed;
bottom: 5px;
right: 5px;
z-index: 9999999999;
padding: 15px;
outline: 1px solid black;
display: flex;
flex-direction: column;
align-items: center;
`
export const ErrTitle = styled.div`
font-size: 24px;
font-family: 'Roboto', sans-serif;
color: #0F1111;
`
export const ErrMsg = styled.div`
font-family: 'Roboto', sans-serif;
margin-top: 10px;
font-size: 15px;

`


export const Header = styled.div`
width: 100%;
height: 10%;
display: flex;
justify-content: flex-start;
align-items: center;
font-size: 15px;
padding: 5px 5px 5px 5px;
font-family: 'Roboto', sans-serif;
font-weight: 600;

p{
    margin: 0;
    padding: 0;
    white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  width: 400px;
}
`
export const SelectMenu = styled.select`
  margin-left: 30px;
  cursor: pointer;

  &:focus-visible{
    outline: none;
  }
`
export const Options = styled.option`
`

