import React, { createContext, useContext, useState } from "react";

const PriceTrackerContext = createContext();

export const PriceTrackerProvider = ({ children }) => {
    const [productPgSelector, setProductPgSelector] = useState(false);
    const [resData, setResData] = useState(null);
    const [productName, setProductName] = useState("");
    const [selectedValue, setSelectedValue] = useState("");
    const [response, setResponse] = useState(false);
    const [prdtId, setPrdtId] = useState(null);

    const contextValue = {
        productPgSelector,
        setProductPgSelector,
        resData,
        setResData,
        productName,
        setProductName,
        selectedValue,
        setSelectedValue,
        response,
        setResponse,
        prdtId,
        setPrdtId,
    };

    return (
        <PriceTrackerContext.Provider value={contextValue}>
            {children}
        </PriceTrackerContext.Provider>
    );
};

export const usePriceTracker = () => {
    return useContext(PriceTrackerContext);
};
