import { Heading } from "./HeadingText.styled";
import Strings from "../../constants/Strings";
import useEcomStore from "../../store";
function HeadingText() {
  const { headingText } = Strings;
  const { amazonExpand, flipkartExpand, spenderId, gender } = useEcomStore();
  return (
    <Heading
      form={
        (amazonExpand || flipkartExpand) && (!spenderId || !gender) ? true : false
      }
    >
      {(amazonExpand || flipkartExpand) && (!spenderId || !gender)
        ? headingText.form
        : headingText.normal}
    </Heading>
  );
}

export default HeadingText;
