import { usePriceTracker } from "../../context/PriceTrackerProvider";
import { ClosingDiv, Header, Options, SelectMenu } from "./PriceTracker.styled"
import { Close } from "@mui/icons-material";
const Title = (props) => {

    const {
  
        productName,
        setSelectedValue,
      } = usePriceTracker();


    const handleSelectChange = (e) => {
        const val = e.target.value;
        // props.onSelectChange(selectedValue);
        setSelectedValue(val)
    };
    const handlClose=()=>{
        props.close(false)
    }
    return (
        <Header>
            <p>{productName}</p>
            <SelectMenu onChange={handleSelectChange}>
                <Options value="3">3 Months</Options>
                <Options value='6'>6 Months</Options>
                <Options value='all'>All</Options>
            </SelectMenu>
            <ClosingDiv onClick={handlClose}>
                <Close />
            </ClosingDiv>
        </Header>
    )
}

export default Title