/* global chrome */
import {
  TemplateContainer,
  NameContainer,
  Img,
  NameImg,
  Title,
  Users,
  DummyUser1,
  DummyUser2,
  UserCount,
} from "./CardTemplate.styled";
import useEcomStore from "../../store";
import Strings from "../../constants/Strings";
import { useEffect } from "react";
import { useState } from "react";
import Loader from "../Loader";
import { checkingOrderUrl } from "../../utils/Amazon";
const zomatoName = chrome.runtime.getURL("./Icons/Flipkart_logo.png");
const swiggyName = chrome.runtime.getURL("./Icons/Amazon_logo.png");
const forward = chrome.runtime.getURL("./Icons/fast-forward.png");
const user1 = chrome.runtime.getURL("./Icons/user1.png");
const user2 = chrome.runtime.getURL("./Icons/user2.png");
const user3 = chrome.runtime.getURL("./Icons/user3.png");
const user4 = chrome.runtime.getURL("./Icons/user4.png");

function CardTemplate({ name, children, disable, expand, setClicked }) {
  const {
    isAmazonPage,
    isFlipkartPage,
    isAmazonLoggedIn,
    isFlipkartLoggedIn,
    amazonNoOrders,
    flipkartNoOrders,
    userCount,
  } = useEcomStore();
  const getTitle = () => {
    if (!expand) return Strings.cardTitle.otherPage;
    if (isAmazonPage) {
      if (isAmazonLoggedIn) {
        if (checkingOrderUrl()) {
          if (amazonNoOrders) return Strings.cardTitle.noOrdersFound;
          return Strings.cardTitle.displayNameRequired;
        } else {
          return Strings.cardTitle.goToOrderSection;
        }
      }
      return Strings.cardTitle.loginRequired;
    }
    if (isFlipkartPage) {
      if (isFlipkartLoggedIn) {
        if (checkingOrderUrl()) {
          if (flipkartNoOrders) return Strings.cardTitle.noOrdersFound;
          return Strings.cardTitle.displayNameRequired;
        } else {
          return Strings.cardTitle.goToOrderSection;
        }
      }
      return Strings.cardTitle.loginRequired;
    }
  };
  const handleClick = () => {
    setClicked(true);
    // changed
    setTimeout(() => {
      setClicked(false);
    },1000)
  };

  return (
    <TemplateContainer
      swiggy={name === "swiggy" ? true : false}
      disable={disable}
      onClick={handleClick}
      expand={expand}
    >
      {!expand ? (
        <Img draggable={false} className="forward-icon" src={forward} />
      ) : null}
      <NameContainer swiggy={name === "swiggy" ? true : false}>
        <NameImg
          draggable={false}
          animate={expand}
          src={name === "swiggy" ? swiggyName : zomatoName}
        />
      </NameContainer>
      <Title>{getTitle()}</Title>
      {children}
      {!expand ? (
        <Users>
          <DummyUser1
            draggable={false}
            src={name === "swiggy" ? user1 : user3}
          />
          <DummyUser2
            draggable={false}
            src={name === "swiggy" ? user2 : user4}
          />
          <UserCount>
            {userCount
              ? name === "swiggy"
                ? `+${userCount.swiggy}k`
                : `+${userCount.zomato}k`
              : "+30k"}
          </UserCount>
        </Users>
      ) : null}
    </TemplateContainer>
  );
}

export default CardTemplate;
