/* global chrome */

import styled, { createGlobalStyle, keyframes } from "styled-components";
import { normalize } from "styled-normalize";
const poppins300 = chrome.runtime.getURL("./fonts/Poppins-Light.ttf");
const poppins400 = chrome.runtime.getURL("./fonts/Poppins-Medium.ttf");
const poppinsItalic400 = chrome.runtime.getURL(
  "./fonts/Poppins-MediumItalic.ttf"
);
const robotoRegular = chrome.runtime.getURL("./fonts/Roboto-Regular.ttf");
const interMedium = chrome.runtime.getURL("./fonts/Inter-Medium.ttf");
export const GlobalStyle = createGlobalStyle`
@import url('https://fonts.googleapis.com/css2?family=Poppins:ital,wght@0,300;0,400;1,400&display=swap'); 
  @font-face {
  font-family: poppins300;
  src: url(${poppins300});
}
  @font-face {
  font-family: poppins-normal;
  src: url(${poppins400});
}
  @font-face {
  font-family: poppins-normal-italic;
  src: url(${poppinsItalic400});
}
  @font-face {
  font-family: inter;
  src: url(${interMedium});
}
  @font-face {
  font-family: roboto;
  src: url(${robotoRegular});
}
`;

const SpinAnime = keyframes`
  0% { -webkit-transform: rotate(0deg);}
  100% { -webkit-transform: rotate(360deg); }
`;

export const Spinner = styled.div`
  margin: auto;
  border: 2px dotted #dbf2ff;
  width: 22px;
  height: 22px;
  display: inline-block;
  position: relative;
  border-radius: 50%;
  border-right: 2px solid #018df7;
  text-align: center;
  animation-name: ${SpinAnime};
  animation-duration: 900ms;
  animation-iteration-count: infinite;
  animation-timing-function: cubic-bezier(0.53, 0.21, 0.29, 0.67);
`;

const LineAnim = keyframes`
  0% {
    left: -40%;
  }
  50% {
    left: 20%;
    width: 80%;
  }
  100% {
    left: 100%;
    width: 100%;
  }
`;

export const LineLoader = styled.div`
  width: 100%;
  height: 3px;
  position: relative;
  overflow: hidden;
  background-color: #ddd;
  margin: 1rem auto;
  -webkit-border-radius: 20px;
  -moz-border-radius: 20px;
  border-radius: 20px;

  ::before {
    content: "";
    position: absolute;
    left: -50%;
    height: 3px;
    width: 40%;
    background-color: #2668b2;
    animation-name: ${LineAnim};
    animation-duration: 900ms;
    animation-iteration-count: infinite;
    -webkit-border-radius: 20px;
    -moz-border-radius: 20px;
    border-radius: 20px;
  }
`;
