/* global chrome */
import { useEffect, useState } from "react";
import Strings from "../constants/Strings";
import {
  Container,
  BackgroundLayer,
  FoodLoader,
  Food,
  Dummy,
  Text,
  LoadingText,
  DotLoader,
  Dot,
} from "./Loader.styled";
const loaderImg1 = chrome.runtime.getURL("./Icons/loaderImg1.png");
const loaderImg2 = chrome.runtime.getURL("./Icons/loaderImg2.png");
const loaderImg3 = chrome.runtime.getURL("./Icons/loaderImg3.png");
const loaderImg4 = chrome.runtime.getURL("./Icons/loaderImg4.png");
const loaderImg5 = chrome.runtime.getURL("./Icons/loaderImg5.png");
const Dishes = chrome.runtime.getURL("./Icons/dishes.png");

const gallery = [loaderImg1, loaderImg2, loaderImg3, loaderImg4, loaderImg5];
const imageIntervalDelay = 2000;

const Loader = ({ loadingTextNeeded }) => {
  const [index, setIndex] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => {
      setIndex((prevIndex) => (prevIndex + 1) % gallery.length);
    }, imageIntervalDelay);

    return () => {
      clearInterval(interval);
    };
  }, []);
  return (
    <Container>
      <BackgroundLayer draggable={false} top src={Dishes} />
      <BackgroundLayer draggable={false} bottom src={Dishes} />
      <Dummy left />
      <FoodLoader />
      <Food draggable={false} src={gallery[index]} />
      <Dummy />
      {loadingTextNeeded ? (
        <Text>
          <LoadingText>{Strings.loadingText}</LoadingText>
          <DotLoader>
            <Dot>.</Dot>
            <Dot second>.</Dot>
            <Dot third>.</Dot>
          </DotLoader>
        </Text>
      ) : null}
    </Container>
  );
};

export default Loader;
