import useEcomStore from "../../store";
import {
  UsersCountLabel,
  LoginInstruction,
} from "../CardTemplate/CardTemplate.styled";
import {
  Form,
  Gender,
  GenderType,
  GenderGradientContainer,
  GenderSelected,
  GenderInputContainer,
  GenderTypeGradientContainer,
  GenderInput,
  GenderLabel,
  DisplayNameInput,
  DisplayNameGradient,
} from "./Content.styled";
import { flipkartOrderPage, amazonOrderPage } from "../../utils/OrderPageUrl";
import Strings from "../../constants/Strings";
import { useState, useEffect } from "react";
import { useRef } from "react";
import { checkingOrderUrl } from "../../utils/Amazon";
function GetCardContent({ contentFor, logged, noOrders }) {
  const {
    spenderId,
    displayName,
    setDisplayName,
    setGender,
    gender,
    setAppActive,
    setStartupFinished,
    setamazonExpand,
    setflipkartExpand,
    isAmazonPage,
    isFlipkartPage,
    isOldUser,
  } = useEcomStore();
  const [showLoginInstruction, setShowLoginInstruction] = useState(false);
  const [maleChecked, setMaleChecked] = useState(false);
  const [femaleChecked, setFemaleChecked] = useState(false);
  const inputRef = useRef(null);

  // useEffect(() => {
  //   localStorage.setItem("displayName", displayName);
  //   localStorage.setItem("gender", gender);
  // }, [displayName, gender]);

  const handleMaleChange = () => {
    setMaleChecked(true);
    setFemaleChecked(false);
  };
  const handleFemaleChange = () => {
    setMaleChecked(false);
    setFemaleChecked(true);
  };
  const handleNameChange = () => {
    setDisplayName(inputRef.current.value);
  };

  const handleClose = () => {
    setAppActive(false);
    setStartupFinished(false);
    setamazonExpand(false);
    setflipkartExpand(false);
  };

  const getForm = () => {
    return (
      <Form>
        <DisplayNameGradient>
          <DisplayNameInput
            ref={inputRef}
            placeholder="Enter display name"
            onChange={handleNameChange}
            activeColor={displayName && displayName !== "" ? true : false}
            value={displayName}
          />
        </DisplayNameGradient>
        <Gender>
          <GenderTypeGradientContainer onClick={handleMaleChange}>
            <GenderType>
              <GenderGradientContainer>
                <GenderInput>
                  {maleChecked ? <GenderSelected /> : null}
                </GenderInput>
              </GenderGradientContainer>
              <GenderLabel activeColor={gender === "male" ? true : false}>
                he/him
              </GenderLabel>
            </GenderType>
          </GenderTypeGradientContainer>
          <GenderTypeGradientContainer onClick={handleFemaleChange}>
            <GenderType>
              <GenderGradientContainer>
                <GenderInput>
                  {femaleChecked ? <GenderSelected /> : null}
                </GenderInput>
              </GenderGradientContainer>
              <GenderLabel activeColor={gender === "female" ? true : false}>
                she/her
              </GenderLabel>
            </GenderType>
          </GenderTypeGradientContainer>
        </Gender>
      </Form>
    );
  };
  useEffect(() => {
    if (
      (logged !== undefined && logged === false) ||
      (!isAmazonPage && !isFlipkartPage)
    ) {
      const timeoutId = setTimeout(() => setShowLoginInstruction(true), 200);
      const closeingTimeoutId = setTimeout(handleClose, 10000);

      return () => {
        clearTimeout(timeoutId);
        clearTimeout(closeingTimeoutId);
      };
    } else {
      setShowLoginInstruction(true);
    }
  }, [logged]);

  useEffect(() => {
    if (noOrders) {
      const timeoutId = setTimeout(() => setShowLoginInstruction(true), 200);
      return () => clearTimeout(timeoutId);
    }
  }, [noOrders]);

  useEffect(() => {
    if (maleChecked) setGender("male");
    if (femaleChecked) setGender("female");
  }, [maleChecked, femaleChecked]);

  switch (contentFor) {
    case "both": {
      return <UsersCountLabel>{"people tried"}</UsersCountLabel>;
    }
    case "swiggy": {
      if (!logged) {
        return showLoginInstruction ? (
          <LoginInstruction>{Strings.loginInstruction}</LoginInstruction>
        ) : null;
      }
      if (!checkingOrderUrl()) {
        return showLoginInstruction ? (
          <LoginInstruction>{amazonOrderPage()}</LoginInstruction>
        ) : null;
      }
      if (noOrders) {
        return showLoginInstruction ? (
          <LoginInstruction>{Strings.noOrdersForSwiggy}</LoginInstruction>
        ) : null;
      }
      return getForm();
    }
    case "zomato": {
      if (!logged) {
        return showLoginInstruction ? (
          <LoginInstruction>{Strings.loginInstruction}</LoginInstruction>
        ) : null;
      }
      if (!checkingOrderUrl()) {
        return showLoginInstruction ? (
          <LoginInstruction>{flipkartOrderPage()}</LoginInstruction>
        ) : null;
      }
      if (noOrders) {
        return showLoginInstruction ? (
          <LoginInstruction>{Strings.noOrdersForZomato}</LoginInstruction>
        ) : null;
      }
      return getForm();
    }
  }
}

export default GetCardContent;
